/// Open a CGNS file for writing (create).
///
/// This is a safe wrapper around [`cg_open`] with `CG_MODE_WRITE`.
/// The HDF5 backend is initialized once on the first call.
/// Returns the CGNS file number on success.
///
/// # Panics
///
/// Panics if the filename contains a null byte.
pub fn open_write(filename: &str) -> Result<i32, String> {
    let _guard = lock_cgns()?;
    ensure_hdf5_backend();
    let c_filename =
        std::ffi::CString::new(filename).map_err(|e| format!("invalid filename: {}", e))?;
    let mut fn_: i32 = 0;
    let status = unsafe { cg_open(c_filename.as_ptr(), CG_MODE_WRITE as i32, &mut fn_) };
    status_to_result(status).map(|_| fn_)
}

/// Open a CGNS file for reading.
///
/// Returns the CGNS file number on success.
pub fn open_read(filename: &str) -> Result<i32, String> {
    let _guard = lock_cgns()?;
    let c_filename =
        std::ffi::CString::new(filename).map_err(|e| format!("invalid filename: {}", e))?;
    let mut fn_: i32 = 0;
    let status = unsafe { cg_open(c_filename.as_ptr(), CG_MODE_READ as i32, &mut fn_) };
    status_to_result(status).map(|_| fn_)
}

/// Open a CGNS file for modification (append).
///
/// Opens an existing file and allows appending new data without
/// overwriting existing content.
pub fn open_modify(filename: &str) -> Result<i32, String> {
    let _guard = lock_cgns()?;
    let c_filename =
        std::ffi::CString::new(filename).map_err(|e| format!("invalid filename: {}", e))?;
    let mut fn_: i32 = 0;
    let status = unsafe { cg_open(c_filename.as_ptr(), CG_MODE_MODIFY as i32, &mut fn_) };
    status_to_result(status).map(|_| fn_)
}

impl_n_fn!(nbocos, cg_nbocos, (fn_: i32, base: i32, zone: i32));

/// Write a boundary condition.
#[allow(clippy::too_many_arguments)]
pub fn boco_write(
    fn_: i32,
    base: i32,
    zone: i32,
    name: &str,
    bocotype: u32,
    ptset_type: u32,
    npnts: i64,
    pnts: &[i64],
) -> Result<i32, String> {
    let _guard = lock_cgns()?;
    let c_name = std::ffi::CString::new(name).map_err(|e| format!("invalid BC name: {}", e))?;
    let mut bc: i32 = 0;
    let status = unsafe {
        cg_boco_write(
            fn_,
            base,
            zone,
            c_name.as_ptr(),
            bocotype,
            ptset_type,
            npnts,
            pnts.as_ptr(),
            &mut bc,
        )
    };
    status_to_result(status).map(|_| bc)
}

/// Read boundary condition metadata.
#[allow(clippy::too_many_arguments)]
pub fn boco_info(
    fn_: i32,
    base: i32,
    zone: i32,
    bc: i32,
    name: &mut [u8],
    bocotype: &mut u32,
    ptset_type: &mut u32,
    npnts: &mut i64,
) -> Result<(), String> {
    let _guard = lock_cgns()?;
    let mut normal_index: i32 = 0;
    let mut normal_list_size: i64 = 0;
    let mut normal_data_type: u32 = 0;
    let mut ndataset: i32 = 0;
    let status = unsafe {
        cg_boco_info(
            fn_,
            base,
            zone,
            bc,
            name.as_mut_ptr() as *mut i8,
            bocotype as *mut u32,
            ptset_type as *mut u32,
            npnts as *mut i64,
            &mut normal_index,
            &mut normal_list_size,
            &mut normal_data_type,
            &mut ndataset,
        )
    };
    status_to_result(status)
}

/// Read boundary condition point data.
///
/// `pnts` must be pre-allocated to the correct size (retrieved via [`boco_info`]).
pub fn boco_read(fn_: i32, base: i32, zone: i32, bc: i32, pnts: &mut [i64]) -> Result<(), String> {
    let _guard = lock_cgns()?;
    let status =
        unsafe { cg_boco_read(fn_, base, zone, bc, pnts.as_mut_ptr(), std::ptr::null_mut()) };
    status_to_result(status)
}

