/// Write an unstructured zone section (element connectivity).
///
/// `elements` is the flat connectivity array (1-based node indices in
/// Fortran order).  Returns the section index on success.
#[allow(clippy::too_many_arguments)]
pub fn section_write(
    fn_: i32,
    base: i32,
    zone: i32,
    name: &str,
    elem_type: u32,
    start: i64,
    end: i64,
    nbndry: i32,
    elements: &[i64],
) -> Result<i32, String> {
    let _guard = lock_cgns()?;
    let c_name =
        std::ffi::CString::new(name).map_err(|e| format!("invalid section name: {}", e))?;
    let mut section_idx: i32 = 0;
    let status = unsafe {
        cg_section_write(
            fn_,
            base,
            zone,
            c_name.as_ptr(),
            elem_type,
            start,
            end,
            nbndry,
            elements.as_ptr(),
            &mut section_idx,
        )
    };
    status_to_result(status).map(|_| section_idx)
}

